using namespace std;

int C(int n, int k) {
    return (n & k) == k;
}

int S(int n, int k) {
    return !(n - k & (k - 1 >> 1));
}

int brute_partition(int n, int m) {
    vector<int> cnt;
    int ans = 0;
    for(int k = 1; k <= n; k++) {
        if(!S(n, k)) continue;
        for(int median = 1; median < m; median++) {
            if(C(median, k - 1)) ans ^= median;
        }
    }
    return ans;
}

void solve() {
    int k, m;
    string s;
    cin >> k >> m >> s;
    int n = 0;
    for(auto &i : s) n += i & 1;
    int ans = brute_partition(n, m);
    cout << ans << '\n';
}

