#include <bits/stdc++.h>

using namespace std;

int S(int n, int k) {
    return !(n - k & (k - 1 >> 1));
}

int get(int n, int m) {
    int L = __lg(n) + 1;
    int up = 1 << L;
    vector<int> dp(up);
    for(int i = 0; i < n; i++) dp[i] = S(n, i + 1);
    for(int j = 0; j < L; j++) {
        for(int i = 0; i < up; i++) {
            if(i >> j & 1) dp[i] ^= dp[i ^ (1 << j)];
        }
    }
    int ans = 0;
    for(int lst = 0; lst < up && lst < m; lst++) {
        if(!dp[lst]) continue;
        int cnt = m - 1 - lst >> L;
        if(cnt & 1 ^ 1) ans ^= lst;
        if(cnt % 4 == 0) ans ^= cnt << L;
        else if(cnt % 4 == 1) ans ^= 1ll << L;
        else if(cnt % 4 == 2) ans ^= cnt + 1 << L;
        else ans ^= 0;
    }
    return ans;
}

void solve() {
    int k, m;
    string s;
    cin >> k >> m >> s;
    int n = 0;
    for(auto &i : s) n += i & 1;
    int ans = get(n, m);
    cout << ans << '\n';
}

signed main() {
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
    int ttt = 1;
    cin >> ttt;
    while(ttt--) {
        solve();
    }
}
